import numpy as np

# arr is the test input (7x24) with colors 5 and 2
rows, cols = arr.shape

# Based on task pattern: fill cells between foreground markers
# Background = 5, Foreground = 2, Fill = 3
bg, fg, fill = 5, 2, 3

output = arr.copy()

for r in range(rows):
    for c in range(cols):
        if output[r, c] == bg:
            row_vals = arr[r, :]
            fg_positions = [x for x in range(cols) if row_vals[x] == fg]

            is_horizontal = False
            for i in range(len(fg_positions) - 1):
                left, right = fg_positions[i], fg_positions[i + 1]
                if left < c < right:
                    is_horizontal = True
                    break

            if not is_horizontal:
                col_vals = arr[:, c]
                fg_pos_rows = [x for x in range(rows) if col_vals[x] == fg]

                is_vertical = False
                for i in range(len(fg_pos_rows) - 1):
                    top, bottom = fg_pos_rows[i], fg_pos_rows[i + 1]
                    if top < r < bottom:
                        is_vertical = True
                        break

            if is_horizontal or is_vertical:
                output[r, c] = fill

output_json = output.tolist()

{'action': 'submit', 'grid': output_json}

